// Metoda z gornym ograniczeniem:
static <T extends Number> double sumOfNumbers(List<T> list) {
    double total = 0;
    for (T n : list) total += n.doubleValue(); // dostepne dzieki extends Number
    return total;
}

// Klasa z ograniczeniem na poziomie calej klasy:
static class NumericBox<T extends Number> {
    private final T value;
    NumericBox(T value) { this.value = value; }
    double asDouble() { return value.doubleValue(); }
}
// new NumericBox<String>(...); // BLAD KOMPILACJI

// Wielokrotne ograniczenia (klasa PIERWSZA, potem interfejsy):
static <T extends Number & Comparable<T>> T max(T a, T b) {
    return (a.compareTo(b) >= 0) ? a : b;
}
max(10, 25); // dziala, Integer implementuje Comparable<Integer> i jest Number
